INSERT INTO `pengaduan` (`id_pengaduan`, `no_pel`, `nama_pel`, `alamat`, `no_tel`, `jenis_aduan`, `wil_layanan`, `isi_aduan`, `foto_aduan`, `tgl_aduan`) VALUES (2, '02002304', 'Cahyadi irawan', 'Jl. Raya kawah Ijen\r\nSumber gading, sumber wringin\r\nBondowoso', '085257319131', 'Air Mati', 'Sukosari 1', 'Air sudah mati 3 hari.. tolong dibantu untuk kelancaran airnya.. saya mengerti apa kegiatan proyek, tp setidaknya 1 hari ada beberapa jam air dihidupkan, bukan mati total.. mohon pengertian dan tanggung jawabnya.. terima kasih', '', '2023-12-31 10:20:56');
