INSERT INTO `pengaduan` (`id_pengaduan`, `no_pel`, `nama_pel`, `alamat`, `no_tel`, `jenis_aduan`, `wil_layanan`, `isi_aduan`, `foto_aduan`, `tgl_aduan`) VALUES (7, '03000305', 'LILIK/BUNASI', 'Dusun Krajan Perumahan Penanggungan RT 13 RW 01 Kecamatan maesan kabupaten bondowoso', '085157606629', 'Lain-lain', 'Maesan', 'Tagihan air perbulan sangat mahal apakah ada kendala atau kebocoran pada pipa dirumah saya 3 bulan sebelumnya tagihan hanya sekitar 50-70rb an tetapi semenjak bulan februari kemaren tagihan saya melunjak sangatlah jauh bisa 2 kali lipat dari tagihan yang sudah saya sebut tadi', '215DD2A9-4DCD-410F-BC9E-42A83B88DCFF.jpeg', '2024-04-02 04:13:43');
INSERT INTO `pengaduan` (`id_pengaduan`, `no_pel`, `nama_pel`, `alamat`, `no_tel`, `jenis_aduan`, `wil_layanan`, `isi_aduan`, `foto_aduan`, `tgl_aduan`) VALUES (8, '7472', 'RIBUT HARIYONO', 'Vila Kembang Asri FB.25, Sukowiryo, Bondowoso', '081331653166', 'Water Meter', 'Bondowoso', 'Pada hari ini, tanggal 04 April 2024 sekitar pkl.10.00 telah datang petugas PDAM Bondowoso ke rumah kami melakukan penggantian meter air (tanpa permintaan/ laporan dari kami). Mohon cek dan konfirmasi apa benar ini aktivitas resmi dari PDAM karena tidak ada dari konfirmasi sebelum/sesudahnya dari pihak PDAM Bondowoso kepada kami. Mohon tindaklanjut. Atas perhatiannya kami sampaikan terimakasih.', 'Meter2.jpeg', '2024-04-04 12:58:03');
