INSERT INTO `pengaduan` (`id_pengaduan`, `no_pel`, `nama_pel`, `alamat`, `no_tel`, `jenis_aduan`, `wil_layanan`, `isi_aduan`, `foto_aduan`, `tgl_aduan`) VALUES (35, '9421', 'Pravita Hermala Wulansari', 'Cluster Wijaya Kusuma Blok I3', '085604982558', 'Pemakaian', 'Bondowoso', 'Tolong di crosscheck pemakaian di bulan november. Karena kami merasa penggunaan air pdam sangat minim sekali. Tatapi tagihannya tinggi. Kami kira ada kebocoran tapi setelah mendatangkan tukang, ternyata tidak ada kebocoran. Tagihan ini lebih banyak saat kami melakukan pembangunan rumah di proses pengecoran lantai 2.', '', '2024-12-11 13:35:27');
