INSERT INTO `pengaduan` (`id_pengaduan`, `no_pel`, `nama_pel`, `alamat`, `no_tel`, `jenis_aduan`, `wil_layanan`, `isi_aduan`, `foto_aduan`, `tgl_aduan`) VALUES (38, '08000135', 'Suwalis', 'Wringin Bondowoso', '085259103626', 'Water Meter', 'Bondowoso', 'Bayarnya setiap bulan sangat mahal, padahal pemakaian seperti biasa.kamar mandi 1 ukuran sedang, 1 ukuran sangat kecil. Sedangkan dibandingkan pemakaian pelanggan lain jauh lebih banyak dan bayarnya hanya dibawah 100rb, sedangkan punya kami pembayaran desember mencapai 360.000, sangat besar sekali. Padahal saya tidak selalu menggunakan pdam, ada sumur juga yg dimanfaatkan untuk mandi dan cuci. Mohon direspon', '', '2025-01-01 11:03:49');
INSERT INTO `pengaduan` (`id_pengaduan`, `no_pel`, `nama_pel`, `alamat`, `no_tel`, `jenis_aduan`, `wil_layanan`, `isi_aduan`, `foto_aduan`, `tgl_aduan`) VALUES (39, '01000610', 'Rawi', 'Jalan Diponegoro gang 1 no 21 kotakulon', '085259001156', 'Air Mati', 'Bondowoso', 'Air mati sejak tgl 6 Januari 2025 pagi hingga malam ini masih belum mengalir', 'IMG20250106195132.jpg', '2025-01-06 19:56:50');
INSERT INTO `pengaduan` (`id_pengaduan`, `no_pel`, `nama_pel`, `alamat`, `no_tel`, `jenis_aduan`, `wil_layanan`, `isi_aduan`, `foto_aduan`, `tgl_aduan`) VALUES (40, '06000067', 'zainullah', 'jl.Prajekwn Kidul Rt.01 Rw.07 Utara Masjid Prajekan Kidul', '081299061400', 'Pemakaian', 'Prajekan', 'tolong di tinjau ulang biaya beban pamakaian PDAM di rumah saya kubikasi tidak sesuai dengan beban pemakain di rumah saya,mohon penjelasan dari pihal PDAM, jangan mengarang klo buat tagihan sesuaikan dengan di lapangan dan pemakaian pelanggan bisa keluar mengunakan jasa PDAM tolong di prioritaskan dan d tinjau ulang', '', '2025-01-06 23:17:55');
INSERT INTO `pengaduan` (`id_pengaduan`, `no_pel`, `nama_pel`, `alamat`, `no_tel`, `jenis_aduan`, `wil_layanan`, `isi_aduan`, `foto_aduan`, `tgl_aduan`) VALUES (41, '06000067', 'zainullah', 'jl.Prajekwn Kidul Rt.01 Rw.07 Utara Masjid Prajekan Kidul', '081299061400', 'Pemakaian', 'Prajekan', 'tolong di tinjau ulang biaya beban pamakaian PDAM di rumah saya kubikasi tidak sesuai dengan beban pemakain di rumah saya,mohon penjelasan dari pihal PDAM, jangan mengarang klo buat tagihan sesuaikan dengan di lapangan dan pemakaian pelanggan bisa keluar mengunakan jasa PDAM tolong di prioritaskan dan d tinjau ulang', '', '2025-01-06 23:18:19');
