INSERT INTO `pengaduan` (`id_pengaduan`, `no_pel`, `nama_pel`, `alamat`, `no_tel`, `jenis_aduan`, `wil_layanan`, `isi_aduan`, `foto_aduan`, `tgl_aduan`) VALUES (43, '01008201', 'Budi setiawan', 'Perum dewata land block c1 nangkaan bondowoso', '081357789688', 'Lain-lain', 'Bondowoso', 'Knp ya beberapa hari ini mandi dengan air dirumah jd gatel\". Tetangga saya juga begitu.. Padahal dulu tidak demikian.', '', '2025-01-07 15:14:49');
INSERT INTO `pengaduan` (`id_pengaduan`, `no_pel`, `nama_pel`, `alamat`, `no_tel`, `jenis_aduan`, `wil_layanan`, `isi_aduan`, `foto_aduan`, `tgl_aduan`) VALUES (44, '01008010', 'Adli Satria Wirawan', 'Perum Dewata Land A-04\r\nKel. Nangkaan', '085335577244', 'Lain-lain', 'Bondowoso', 'Airnya setiap kali dibuat mandi gatal-gatal.', '', '2025-01-07 15:22:41');
INSERT INTO `pengaduan` (`id_pengaduan`, `no_pel`, `nama_pel`, `alamat`, `no_tel`, `jenis_aduan`, `wil_layanan`, `isi_aduan`, `foto_aduan`, `tgl_aduan`) VALUES (45, '01008007', 'Herlin Kurniyanti', 'Dewata land no. A08 Nangkaan Bondowoso', '082228950178', 'Lain-lain', 'Bondowoso', 'setelah pakai air PDAM, contohnya mandi dll, badan menjadi gatal2, kemerahan, Sejak kemaren, keluhan dirasakan seluruh anggota rumah yg menggunakan air PDAM, kepada PDAM mohon diperhatikan kmbali air saluran ke nangkaan kenapa bisa menjadi gatal2 setelah pakai air PDAM, Terimakasih atas perhatiannya, semoga direspon????', '', '2025-01-07 19:07:17');
INSERT INTO `pengaduan` (`id_pengaduan`, `no_pel`, `nama_pel`, `alamat`, `no_tel`, `jenis_aduan`, `wil_layanan`, `isi_aduan`, `foto_aduan`, `tgl_aduan`) VALUES (46, '01008010', 'Adli Satria Wirawan', 'Perum Dewata Land A-04\r\nNangkaan', '085335577244', 'Lain-lain', 'Bondowoso', 'Seminggu lebih air nya dipake mandi bikin gatal². Kenapa ya kak? \r\nAnak saya sampe gak mau mandi. \r\nAir berkali-kali dikuraa tetep aja bikin gatal.', '', '2025-01-10 13:55:00');
