#
# TABLE STRUCTURE FOR: arsip
#

DROP TABLE IF EXISTS `arsip`;

CREATE TABLE `arsip` (
  `id_arsip` int NOT NULL,
  `jenis` enum('Surat Keputusan','Peraturan','Berkas Kerja','dokumen') NOT NULL,
  `tahun` char(4) NOT NULL,
  `nama_file` varchar(255) NOT NULL,
  `nama_dokumen` varchar(255) NOT NULL,
  `tentang` text NOT NULL,
  `tgl_dokumen` date NOT NULL,
  `tgl_upload` date NOT NULL,
  `keterangan` text NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;



#
# TABLE STRUCTURE FOR: bagian
#

DROP TABLE IF EXISTS `bagian`;

CREATE TABLE `bagian` (
  `id_bagian` int NOT NULL,
  `nama_bagian` varchar(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;



#
# TABLE STRUCTURE FOR: jabatan
#

DROP TABLE IF EXISTS `jabatan`;

CREATE TABLE `jabatan` (
  `id_jabatan` int NOT NULL,
  `nama_jabatan` varchar(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;



#
# TABLE STRUCTURE FOR: karyawan
#

DROP TABLE IF EXISTS `karyawan`;

CREATE TABLE `karyawan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_bagian` int NOT NULL,
  `id_subag` int NOT NULL,
  `id_jabatan` int NOT NULL,
  `nama` varchar(256) NOT NULL,
  `alamat` varchar(256) NOT NULL,
  `agama` varchar(50) NOT NULL,
  `status_pegawai` varchar(50) NOT NULL,
  `nik` varchar(8) NOT NULL,
  `no_hp` varchar(13) NOT NULL,
  `jenkel` varchar(50) NOT NULL,
  `tmp_lahir` varchar(50) NOT NULL,
  `tgl_lahir` date NOT NULL,
  `tgl_masuk` date NOT NULL,
  `aktif` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `id_bagian` (`id_bagian`),
  KEY `id_subag` (`id_subag`),
  KEY `id_jabatan` (`id_jabatan`)
) ENGINE=InnoDB AUTO_INCREMENT=189 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;



#
# TABLE STRUCTURE FOR: nama_upk
#

DROP TABLE IF EXISTS `nama_upk`;

CREATE TABLE `nama_upk` (
  `id_upk` int NOT NULL,
  `nama_upk` varchar(100) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;



#
# TABLE STRUCTURE FOR: pengaduan
#

DROP TABLE IF EXISTS `pengaduan`;

CREATE TABLE `pengaduan` (
  `id_pengaduan` int NOT NULL AUTO_INCREMENT,
  `no_pel` varchar(8) NOT NULL,
  `nama_pel` varchar(50) NOT NULL,
  `alamat` text NOT NULL,
  `no_tel` varchar(15) NOT NULL,
  `jenis_aduan` enum('Air Mati','Air Keruh','Kebocoran','Water Meter','Pemakaian','Lain-lain') NOT NULL,
  `wil_layanan` enum('Bondowoso','Sukosari 1','Maesan','Tegalampel','Tapen','Prajekan','Tlogosari','Wringin','Curahdami','Tamanan','Tenggarang','Tamankrocok','Wonosari','Klabang','Sukosari 2') NOT NULL,
  `isi_aduan` text NOT NULL,
  `foto_aduan` varchar(50) NOT NULL,
  `tgl_aduan` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_pengaduan`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;



#
# TABLE STRUCTURE FOR: subag
#

DROP TABLE IF EXISTS `subag`;

CREATE TABLE `subag` (
  `id_subag` int NOT NULL,
  `nama_subag` varchar(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;



#
# TABLE STRUCTURE FOR: user
#

DROP TABLE IF EXISTS `user`;

CREATE TABLE `user` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nama_pengguna` varchar(100) NOT NULL,
  `nama_lengkap` varchar(100) NOT NULL,
  `email` varchar(100) NOT NULL,
  `password` varchar(256) NOT NULL,
  `level` varchar(50) NOT NULL DEFAULT 'Pengguna',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;



